namespace SharpSense.Infrastructure.Indexing.TypeScript;

internal static class TypeScriptGeneratedFileDetector
{
    private static readonly string[] _generatedFileSuffixes =
    [
        ".generated.ts",
        ".generated.tsx",
        ".gen.ts",
        ".gen.tsx",
        ".pb.ts"
    ];

    private static readonly string[] _generatedHeaderMarkers =
    [
        "@generated",
        "<auto-generated",
        "auto-generated",
        "generated by ",
        "automatically generated",
        "do not edit"
    ];

    public static bool IsGenerated(string relativeFilePath, string sourceText)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(relativeFilePath);
        ArgumentNullException.ThrowIfNull(sourceText);

        foreach (var suffix in _generatedFileSuffixes)
        {
            if (relativeFilePath.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return HasGeneratedHeaderComment(sourceText);
    }

    private static bool HasGeneratedHeaderComment(string sourceText)
    {
        var span = sourceText.AsSpan();
        var index = 0;
        if (span.Length > 0 && span[0] == '\uFEFF')
        {
            index = 1;
        }

        while (index < span.Length)
        {
            while (index < span.Length && char.IsWhiteSpace(span[index]))
            {
                index++;
            }

            if (index >= span.Length)
            {
                return false;
            }

            if (index + 1 < span.Length && span[index] == '/' && span[index + 1] == '/')
            {
                var lineStart = index + 2;
                var lineEnd = lineStart;
                while (lineEnd < span.Length && span[lineEnd] is not '\n' and not '\r')
                {
                    lineEnd++;
                }

                if (ContainsMarker(span[lineStart..lineEnd]))
                {
                    return true;
                }

                index = lineEnd;
                continue;
            }

            if (index + 1 < span.Length && span[index] == '/' && span[index + 1] == '*')
            {
                var blockStart = index + 2;
                var closingOffset = span[blockStart..].IndexOf("*/", StringComparison.Ordinal);
                var blockEnd = closingOffset >= 0 ? blockStart + closingOffset : span.Length;
                if (ContainsMarker(span[blockStart..blockEnd]))
                {
                    return true;
                }

                index = closingOffset >= 0 ? blockEnd + 2 : span.Length;
                continue;
            }

            // Stop at the first non-comment code token so string literals in code never match.
            return false;
        }

        return false;
    }

    private static bool ContainsMarker(ReadOnlySpan<char> commentText)
    {
        foreach (var marker in _generatedHeaderMarkers)
        {
            if (commentText.Contains(marker.AsSpan(), StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }
}
